import{I as o,o as l,c as p,j as a,a as i,J as h,w as t,b6 as d}from"./chunks/framework.BUXTSoD9.js";const s={style:{margin:"50px 0"}},k=JSON.parse('{"title":"Tim y tuong tot - tu nhu cau nguoi dung den san pham co nguoi tra tien","description":"Hoc cach phat hien co hoi tu nhung noi dau hang ngay, phan tich nhu cau co he thong, va mai dua mot y tuong binh thuong thanh khai niem san pham ma nguoi dung san sang tra tien.","frontmatter":{"title":"Tim y tuong tot - tu nhu cau nguoi dung den san pham co nguoi tra tien","description":"Hoc cach phat hien co hoi tu nhung noi dau hang ngay, phan tich nhu cau co he thong, va mai dua mot y tuong binh thuong thanh khai niem san pham ma nguoi dung san sang tra tien."},"headers":[],"relativePath":"vi-vn/stage-1/finding-great-idea/index.md","filePath":"vi-vn/stage-1/finding-great-idea/index.md"}'),r={name:"vi-vn/stage-1/finding-great-idea/index.md"},v=Object.assign(r,{setup(m){const u="Khoang <strong>3 gio</strong>";return(b,n)=>{const e=o("ChapterIntroduction"),g=o("StepBar"),c=o("ClientOnly");return l(),p("div",null,[n[1]||(n[1]=a("h1",{id:"so-cap-2-tim-y-tuong-tot",tabindex:"-1"},[i("So cap 2: Tim y tuong tot "),a("a",{class:"header-anchor",href:"#so-cap-2-tim-y-tuong-tot","aria-label":"Permalink to “So cap 2: Tim y tuong tot”"},"​")],-1)),n[2]||(n[2]=a("h2",{id:"dan-nhap-chuong",tabindex:"-1"},[i("Dan nhap chuong "),a("a",{class:"header-anchor",href:"#dan-nhap-chuong","aria-label":"Permalink to “Dan nhap chuong”"},"​")],-1)),h(e,{duration:u,tags:["Khai pha nhu cau","Tu duy san pham","Phan tich nguoi dung","Mo hinh kinh doanh"],coreOutput:"3 khai niem san pham da duoc kiem chung",expectedOutput:"Huong san pham/co hoi khoi nghiep co the trien khai"},{default:t(()=>[...n[0]||(n[0]=[a("p",null,"O chuong truoc, ban da thay AI IDE co the giup ta tao ra san pham rat nhanh. Nhung truoc khi viet dong code dau tien, co mot cau hoi can ban hon:",-1),a("p",null,[a("strong",null,"Minh se lam cai gi?")],-1),a("p",null,[i('Rat nhieu nguoi bat dau bang "lam mot cong cu AI" hoac "lam mot mang xa hoi", nhung lam xong thi khong ai dung. Van de thuong nam o dau? '),a("strong",null,"Chua tim duoc nhu cau that.")],-1),a("p",null,[i("Thuc te con kho hon: "),a("strong",null,"co san pham giai quyet dung van de nhung nguoi dung van khong muon tra tien"),i(".")],-1),a("p",null,"Trong chuong nay, thong qua cau chuyen cua Minh, ban se hoc mot phuong phap hoan chinh de tim y tuong: tu tieu chuan danh gia, khai pha noi dau, phan nhom nguoi dung, dao sau boi canh, kiem chung nhu cau, va mai dua khai niem san pham.",-1)])]),_:1}),a("div",s,[h(c,null,{default:t(()=>[h(g,{active:0,items:[{title:"Step 1",description:"Xay tieu chuan danh gia"},{title:"Step 2",description:"Khai pha noi dau hang ngay"},{title:"Step 3",description:"Phan nhom nguoi dung theo chieu ngang"},{title:"Step 4",description:"Dao sau boi canh theo chieu doc"},{title:"Step 5",description:"Kiem chung nhu cau that/gia"},{title:"Step 6",description:"Mai dua khai niem san pham"}]})]),_:1})]),n[3]||(n[3]=d(`<h2 id="step-1-xay-tieu-chuan-danh-gia-nhu-cau-nao-khien-nguoi-dung-san-sang-tra-tien" tabindex="-1">Step 1: Xay tieu chuan danh gia - nhu cau nao khien nguoi dung san sang tra tien <a class="header-anchor" href="#step-1-xay-tieu-chuan-danh-gia-nhu-cau-nao-khien-nguoi-dung-san-sang-tra-tien" aria-label="Permalink to “Step 1: Xay tieu chuan danh gia - nhu cau nao khien nguoi dung san sang tra tien”">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Vi sao chuong nay quan trong?</p><p>Co the ban se nghi: &quot;Day la khoa hoc Vibe Coding, sao lai hoc tim nhu cau truoc? Khong viet code luon duoc a?&quot;</p><p>Rat nhieu khoa hoc lap trinh bat dau bang du an: Todo List, may tinh, blog ca nhan... Nhung neu huong di sai, ban cang lam nhieu cang xa muc tieu.</p><p>Hay tuong tuong:</p><ul><li>Ban bo 2 tuan lam &quot;he thong quan ly lich&quot;, trong khi thi truong da co hang tram san pham tot hon.</li><li>Ban lam app &quot;chup anh tinh calo&quot;, nhung nguoi dung dung 1 lan roi go.</li><li>Ban lam &quot;so chi tieu ca nhan&quot;, nhung chinh ban cung it dung.</li></ul><p>Lam xong, ban co cam thay tu tin de coi do la &quot;mot san pham dang gia&quot; khong? Thuong la khong, vi no khong giai quyet van de that, khong tao gia tri that.</p><p>Vibe Coding lam cho viec bien y tuong thanh san pham nhanh hon. Chinh vi nhanh, ta can biet <strong>chuyen gi dang lam</strong>.</p></div><h3 id="tieu-chuan-danh-gia-y-tuong-ban-nen-ghi-ra" tabindex="-1">Tieu chuan danh gia y tuong (ban nen ghi ra) <a class="header-anchor" href="#tieu-chuan-danh-gia-y-tuong-ban-nen-ghi-ra" aria-label="Permalink to “Tieu chuan danh gia y tuong (ban nen ghi ra)”">​</a></h3><p>Mot y tuong &quot;dang lam&quot; thuong can dat toi thieu 4 tieu chuan:</p><ol><li><strong>Co nguoi gap van de thuong xuyen</strong>: khong phai mot tinh huong hiem.</li><li><strong>Van de co gia tri</strong>: tiet kiem thoi gian, tien bac, rui ro, hoac giam dau dau.</li><li><strong>Nguoi dung co dong luc hanh dong</strong>: ho san sang thay doi hanh vi de giai quyet.</li><li><strong>Ban co cach tiep can</strong>: ban biet tim nguoi dung o dau va co the lay phan hoi.</li></ol><p>Neu y tuong chi &quot;nghe hay&quot; nhung khong ro ai can, can nhu the nao, va vi sao ho tra tien, thi rat de lam xong roi... khong ai dung.</p><h2 id="mo-dau-cau-chuyen-cua-minh" tabindex="-1">Mo dau: cau chuyen cua Minh <a class="header-anchor" href="#mo-dau-cau-chuyen-cua-minh" aria-label="Permalink to “Mo dau: cau chuyen cua Minh”">​</a></h2><p>Minh la mot lap trinh vien da di lam 3 nam. Mot ngay, Minh nghi: &quot;Hay lam mot app the hinh giup nguoi dung len ke hoach tap va ghi lai du lieu tap luyen.&quot; Minh rat hao hung vi cam thay minh tim duoc mot du an lon.</p><p>Mot nam tiep theo, Minh danh het thoi gian ranh de lam app: khoa hoc, check-in, cong dong, phan tich du lieu... giao dien cung dep (theo Minh thay).</p><p>Ngay ra mat, Minh chi tien quang ba. Thang dau co 50.000 luot tai. Nghe co ve tot.</p><p>Nhung van de den nhanh:</p><ul><li>Nguoi dung tai ve dung 1 lan roi go.</li><li>Ty le quay lai sau 7 ngay rat thap.</li><li>Tinh nang tra phi gan nhu khong ai mua.</li><li>Thi truong da co san pham truong thanh voi noi dung va he sinh thai manh.</li></ul><p>Minh lo nang va tu hoi: &quot;Minh lam cung on ma, sao khong ai dung?&quot;</p><p>Van de khong phai Minh thieu ky thuat. Van de nam o <strong>diem xuat phat</strong>: Minh chua lam ro cau hoi can ban nhat: <strong>nguoi dung co that su can them mot app nay khong, va vi sao ho se tra tien?</strong></p><p>Tu do, ta rut ra bai hoc: <strong>huong di sai thi cang di sau cang sai</strong>.</p><div class="tip custom-block"><p class="custom-block-title">Chuong nay ban se lam gi?</p><p>Ban se di qua 3 man:</p><ol><li>Tim nhu cau that: nhu cau nao co gia tri va co the tra tien.</li><li>Dao ra y tuong tot: tu noi dau hang ngay tao thanh co hoi san pham.</li><li>Mai dua bang AI: dung AI de bien y tuong thanh phuong an co the trien khai va kiem chung.</li></ol></div><h2 id="step-2-khai-pha-noi-dau-hang-ngay" tabindex="-1">Step 2: Khai pha noi dau hang ngay <a class="header-anchor" href="#step-2-khai-pha-noi-dau-hang-ngay" aria-label="Permalink to “Step 2: Khai pha noi dau hang ngay”">​</a></h2><p>Nguon y tuong on dinh nhat thuong den tu &quot;noi dau hang ngay&quot;. Cach lam don gian:</p><ol><li>Viet ra 20 viec/boi canh ban (hoac nguoi xung quanh) lap lai hang tuan.</li><li>Danh dau nhung cho &quot;mat thoi gian&quot;, &quot;de sai&quot;, &quot;de quen&quot;, &quot;de tre han&quot;, &quot;de bi phat&quot;.</li><li>Moi muc, ghi them: ai dang bi dau dau? khi nao? tai sao? hau qua la gi?</li></ol><p>Vi du noi dau:</p><ul><li>Lam bao cao hang tuan mat nhieu thoi gian.</li><li>Chat voi khach hang qua nhieu kenh, bi sot tin.</li><li>Sap xep tai lieu/anh/video rui tung, moi lan tim rat lau.</li><li>Duyet hop dong dai, de bo sot rui ro.</li></ul><p>Quan trong: dung dung o &quot;van de&quot; chung chung. Hay dich no thanh hanh vi va boi canh cu the.</p><h2 id="step-3-phan-nhom-nguoi-dung-theo-chieu-ngang" tabindex="-1">Step 3: Phan nhom nguoi dung theo chieu ngang <a class="header-anchor" href="#step-3-phan-nhom-nguoi-dung-theo-chieu-ngang" aria-label="Permalink to “Step 3: Phan nhom nguoi dung theo chieu ngang”">​</a></h2><p>Mot y tuong co the dung voi nhieu nhom nguoi, nhung moi nhom co &quot;gia tri&quot; va &quot;kha nang tra tien&quot; khac nhau.</p><p>Hay phan nhom theo:</p><ul><li>Nghe nghiep/vi tri: van hanh, ke toan, HR, sales, giao vien, sinh vien...</li><li>Quy mo: ca nhan, nhom nho, doanh nghiep.</li><li>Tan suat: dung hang ngay hay thinh thoang?</li><li>Chi phi cua van de: mat 10 phut hay mat 5 gio?</li></ul><p>Muc tieu cua buoc nay: chon ra 1-2 nhom ma ban co the tiep can de phong van va kiem chung.</p><h2 id="step-4-dao-sau-boi-canh-theo-chieu-doc" tabindex="-1">Step 4: Dao sau boi canh theo chieu doc <a class="header-anchor" href="#step-4-dao-sau-boi-canh-theo-chieu-doc" aria-label="Permalink to “Step 4: Dao sau boi canh theo chieu doc”">​</a></h2><p>De mo ta ro nhu cau, ban can biet:</p><ol><li>Nguoi dung bat dau tu dau? (dau vao)</li><li>Ho thuong lam gi tiep theo? (cac buoc)</li><li>Cho nao hay bi ket? (nut that)</li><li>Sai sot thuong xay ra o dau? (rui ro)</li><li>Sau khi xong, ho can dau ra gi? (ket qua)</li></ol><p>De lam nhanh, hay ve 1 &quot;luong cong viec&quot; gom 5-7 buoc. AI rat hop de giup ban sap xep va lam ro luong nay.</p><h2 id="step-5-kiem-chung-nhu-cau-that-gia" tabindex="-1">Step 5: Kiem chung nhu cau that/gia <a class="header-anchor" href="#step-5-kiem-chung-nhu-cau-that-gia" aria-label="Permalink to “Step 5: Kiem chung nhu cau that/gia”">​</a></h2><p>Nhieu y tuong nghe co ve hop ly nhung thuc ra la &quot;nhu cau gia&quot;. Cach kiem chung:</p><ul><li><strong>Hoi ve hanh vi qua khu</strong> thay vi y kien chung chung.</li><li><strong>Hoi chi tiet chi phi</strong>: mat bao lau, mat bao nhieu tien, bi anh huong ra sao.</li><li><strong>Hoi giai phap hien tai</strong>: ho dang dung gi de giai quyet? co phai ho da tu lam cach khac?</li><li><strong>Hoi nguong tra tien</strong>: trong tinh huong nao ho san sang tra?</li></ul><p>Goi y cau hoi phong van:</p><ol><li>Lan gan nhat ban gap van de nay la khi nao? Ban dang lam gi?</li><li>Ban da thu giai phap nao? Vi sao khong on?</li><li>Neu giai quyet duoc, ban duoc loi gi? (thoi gian, tien, rui ro, tinh than)</li><li>Neu co cong cu giai quyet, ban muon no lam gi truoc? Cai gi la &quot;bat buoc&quot;?</li></ol><h2 id="step-6-mai-dua-khai-niem-san-pham" tabindex="-1">Step 6: Mai dua khai niem san pham <a class="header-anchor" href="#step-6-mai-dua-khai-niem-san-pham" aria-label="Permalink to “Step 6: Mai dua khai niem san pham”">​</a></h2><p>Den day, ban co 3 thanh phan:</p><ol><li>Mot nhom nguoi dung ro rang.</li><li>Mot boi canh ro rang.</li><li>Mot noi dau ro rang va co chi phi.</li></ol><p>Gio hay viet 1 cau &quot;dinh nghia san pham&quot; theo mau:</p><blockquote><p>Doi voi [nhom nguoi dung], trong boi canh [tinh huong cu the], san pham nay giup ho [muc tieu] bang cach [cach lam], de giam [chi phi] va dat duoc [ket qua].</p></blockquote><p>Vi du:</p><blockquote><p>Doi voi nhan vien van hanh TMĐT, khi can tao nhanh noi dung cho nhieu san pham, cong cu nay giup tao ban nhap anh va copy theo mau, de giam thoi gian lam thu cong va tang toc do len hang.</p></blockquote><h3 id="dung-ai-de-mai-dua-prompt-mau" tabindex="-1">Dung AI de mai dua (prompt mau) <a class="header-anchor" href="#dung-ai-de-mai-dua-prompt-mau" aria-label="Permalink to “Dung AI de mai dua (prompt mau)”">​</a></h3><p>Ban co the dua y tuong cho AI de:</p><ul><li>viet lai mo ta cho ro rang hon,</li><li>de xuat 3 phien ban &quot;dinh vi san pham&quot; khac nhau,</li><li>de xuat 10 cau hoi phong van,</li><li>de xuat 3 gia thuyet nguoi dung va cach test.</li></ul><p>Prompt goi y:</p><div class="language-txt"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Toi co y tuong san pham sau:</span></span>
<span class="line"><span>[dan noi dung o day]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Hay giup toi:</span></span>
<span class="line"><span>1. Viet lai thanh 1 cau mo ta ro rang (1-2 cau).</span></span>
<span class="line"><span>2. Liet ke 5 tinh huong nguoi dung that su gap van de.</span></span>
<span class="line"><span>3. Viet 10 cau hoi phong van de kiem chung.</span></span>
<span class="line"><span>4. De xuat 3 phien ban dinh vi san pham khac nhau.</span></span></code></pre></div><h2 id="bai-tap" tabindex="-1">Bai tap <a class="header-anchor" href="#bai-tap" aria-label="Permalink to “Bai tap”">​</a></h2><ol><li>Viet ra 10 noi dau hang ngay ban gap (hoac nguoi than ban be gap).</li><li>Chon 2 noi dau co chi phi ro rang va co nguoi co the phong van ngay.</li><li>Viet 1 cau &quot;dinh nghia san pham&quot; theo mau o tren.</li><li>Viet 10 cau hoi phong van va phong van it nhat 1 nguoi that.</li></ol><p>Khi ban co 3 phan: nguoi dung + boi canh + noi dau, viec dung AI IDE de tao prototype se de hon rat nhieu.</p>`,51))])}}});export{k as __pageData,v as default};
